#!/usr/bin/env bash

# File paths
SETTINGS_FILE="$HOME/.config/hypr/settings.json"
WEATHER_SCRIPT="$HOME/.config/hypr/scripts/weather.sh"
ENV_FILE="$HOME/.config/hypr/scripts/quickshell/calendar/.env"

# Niri config paths
NIRI_CONF_DIR="$HOME/.config/niri"
NIRI_TMPL_DIR="$HOME/.config/niri/templates"
NIRI_CONFIG="$NIRI_CONF_DIR/config.kdl"

# Hyprland colors path (generated by matugen, read for color extraction)
COLORS_CONF="$HOME/.config/hypr/colors.conf"

# ZSH env sync
ZSH_RC="$HOME/.zshrc"

# Ensure required directories and files exist
mkdir -p "$NIRI_CONF_DIR" "$NIRI_TMPL_DIR" "$(dirname "$SETTINGS_FILE")" "$(dirname "$ENV_FILE")"
[ ! -f "$SETTINGS_FILE" ] && echo "{}" > "$SETTINGS_FILE"

# ─────────────────────────────────────────────────────────────────────────────
# translate_mods: "SUPER&SHIFT_L" → "Mod+Shift"
# ─────────────────────────────────────────────────────────────────────────────
translate_mods() {
    echo "$1" \
        | sed 's/\$mainMod/SUPER/g' \
        | sed 's/SUPER/Mod/g' \
        | sed 's/SHIFT_L\|SHIFT_R\|SHIFT/Shift/g' \
        | sed 's/\bCTRL\b\|CONTROL/Ctrl/g' \
        | sed 's/\bALT\b/Alt/g' \
        | sed 's/[& ,]\+/+/g' \
        | sed 's/^+//; s/+$//'
}

# ─────────────────────────────────────────────────────────────────────────────
# translate_key: Hyprland key name → niri key name
# ─────────────────────────────────────────────────────────────────────────────
translate_key() {
    case "${1^^}" in
        RETURN|ENTER)   echo "Return"    ;;
        SPACE)          echo "Space"     ;;
        ESCAPE|ESC)     echo "Escape"    ;;
        TAB)            echo "Tab"       ;;
        DELETE|DEL)     echo "Delete"    ;;
        BACKSPACE)      echo "BackSpace" ;;
        *)              echo "$1"        ;;
    esac
}

compile_settings() {
    echo "Regenerating niri config from template..."

    TMPL="$NIRI_TMPL_DIR/config.kdl.template"
    if [ ! -f "$TMPL" ]; then
        echo "ERROR: niri config template not found at $TMPL" >&2
        return 1
    fi

    TMP_DIR=$(mktemp -d)
    TMP_CONFIG="${NIRI_CONFIG}.tmp"

    # ── Read settings.json values ─────────────────────────────────────────
    LANG=$(jq -r '.language // "us"' "$SETTINGS_FILE")
    KB_OPT=$(jq -r '.kbOptions // "grp:alt_shift_toggle"' "$SETTINGS_FILE")
    MOUSE_SENSITIVITY=$(jq -r '.mouseSensitivity // "-0.1"' "$SETTINGS_FILE")
    TOUCHPAD_SENSITIVITY=$(jq -r '.touchpadSensitivity // "0.8"' "$SETTINGS_FILE")
    WP_DIR=$(jq -r '.wallpaperDir // empty' "$SETTINGS_FILE")

    # ── Extract matugen colors (fallback to green/gray if not yet generated) ──
    ACTIVE_COLOR="#00FF41"
    INACTIVE_COLOR="#333333"
    if [ -f "$COLORS_CONF" ]; then
        _ac=$(grep -oP 'active_border\s*=\s*rgba\(\K[0-9a-fA-F]{6}' "$COLORS_CONF" 2>/dev/null | head -1)
        _ic=$(grep -oP 'inactive_border\s*=\s*rgba\(\K[0-9a-fA-F]{6}' "$COLORS_CONF" 2>/dev/null | head -1)
        [ -n "$_ac" ] && ACTIVE_COLOR="#${_ac}"
        [ -n "$_ic" ] && INACTIVE_COLOR="#${_ic}"
    fi

    # ── Build hardware environment block → $TMP_DIR/env_block ────────────
    # hardwareEnvs entries stored as "KEY=VALUE" format
    > "$TMP_DIR/env_block"
    while IFS= read -r entry; do
        [ -z "$entry" ] && continue
        hw_key="${entry%%=*}"
        hw_val="${entry#*=}"
        printf '    %s "%s"\n' "$hw_key" "$hw_val" >> "$TMP_DIR/env_block"
    done < <(jq -r '.hardwareEnvs[]? // empty' "$SETTINGS_FILE" 2>/dev/null)

    # ── Build monitor output blocks → $TMP_DIR/output_blocks ─────────────
    > "$TMP_DIR/output_blocks"
    MONITOR_COUNT=$(jq '.monitors | length' "$SETTINGS_FILE" 2>/dev/null || echo 0)
    if [[ "$MONITOR_COUNT" -gt 0 ]]; then
        while IFS= read -r mon_json; do
            MON_NAME=$(echo "$mon_json"  | jq -r '.name')
            MON_W=$(echo "$mon_json"     | jq -r '.resW')
            MON_H=$(echo "$mon_json"     | jq -r '.resH')
            MON_RATE=$(echo "$mon_json"  | jq -r '.rate')
            MON_X=$(echo "$mon_json"     | jq -r '.x // 0')
            MON_Y=$(echo "$mon_json"     | jq -r '.y // 0')
            MON_SCALE=$(echo "$mon_json" | jq -r '.scale // 1.0')
            MON_TNUM=$(echo "$mon_json"  | jq -r '.transform // 0')

            case "$MON_TNUM" in
                1) MON_TRANSFORM="90"          ;;
                2) MON_TRANSFORM="180"         ;;
                3) MON_TRANSFORM="270"         ;;
                4) MON_TRANSFORM="flipped"     ;;
                5) MON_TRANSFORM="flipped-90"  ;;
                6) MON_TRANSFORM="flipped-180" ;;
                7) MON_TRANSFORM="flipped-270" ;;
                *) MON_TRANSFORM="normal"      ;;
            esac

            {
                printf 'output "%s" {\n' "$MON_NAME"
                printf '    mode "%sx%s@%s"\n' "$MON_W" "$MON_H" "$MON_RATE"
                printf '    position x=%s y=%s\n' "$MON_X" "$MON_Y"
                printf '    scale %s\n' "$MON_SCALE"
                printf '    transform "%s"\n' "$MON_TRANSFORM"
                printf '}\n\n'
            } >> "$TMP_DIR/output_blocks"
        done < <(jq -c '.monitors[]?' "$SETTINGS_FILE" 2>/dev/null)
    fi

    # ── Build spawn-at-startup entries → $TMP_DIR/spawn ──────────────────
    > "$TMP_DIR/spawn"
    while IFS= read -r cmd; do
        [ -z "$cmd" ] && continue
        escaped="${cmd//\\/\\\\}"
        escaped="${escaped//\"/\\\"}"
        printf 'spawn-at-startup "bash" "-c" "%s"\n' "$escaped" >> "$TMP_DIR/spawn"
    done < <(jq -r '.startup[]?.command // empty' "$SETTINGS_FILE" 2>/dev/null)

    if [[ $(jq -r 'if (if type == "object" and has("openGuideAtStartup") then .openGuideAtStartup else true end) then "yes" else "no" end' "$SETTINGS_FILE") == "yes" ]]; then
        printf 'spawn-at-startup "bash" "-c" "sleep 1 && ~/.config/hypr/scripts/qs_manager.sh toggle guide"\n' >> "$TMP_DIR/spawn"
    fi

    # ── Build dynamic keybinds → $TMP_DIR/keybinds ───────────────────────
    > "$TMP_DIR/keybinds"
    while IFS=$'\t' read -r kb_mods kb_key kb_dispatcher kb_command; do
        [[ "$kb_dispatcher" != "exec" ]] && continue

        niri_mods=$(translate_mods "$kb_mods")
        niri_key=$(translate_key "$kb_key")

        if [[ -n "$niri_mods" ]]; then
            bind_key="${niri_mods}+${niri_key}"
        else
            bind_key="${niri_key}"
        fi

        escaped_cmd="${kb_command//\\/\\\\}"
        escaped_cmd="${escaped_cmd//\"/\\\"}"
        printf '    %s { spawn "bash" "-c" "%s"; }\n' "$bind_key" "$escaped_cmd" >> "$TMP_DIR/keybinds"
    done < <(jq -r '.keybinds[]? | [(.mods // ""), (.key // ""), (.dispatcher // "exec"), (.command // "")] | @tsv' "$SETTINGS_FILE" 2>/dev/null)

    # ── Sync ZSH_RC wallpaper dir ─────────────────────────────────────────
    if [ -n "$WP_DIR" ] && [ -f "$ZSH_RC" ]; then
        sed -i "s|^export WALLPAPER_DIR=.*|export WALLPAPER_DIR=\"$WP_DIR\"|" "$ZSH_RC"
    fi

    # ── Assemble final config via Python (handles multiline substitution) ──
    /run/current-system/sw/bin/python3 - \
        "$TMPL" \
        "$TMP_CONFIG" \
        "$LANG" \
        "$KB_OPT" \
        "$MOUSE_SENSITIVITY" \
        "$TOUCHPAD_SENSITIVITY" \
        "$ACTIVE_COLOR" \
        "$INACTIVE_COLOR" \
        "$TMP_DIR/output_blocks" \
        "$TMP_DIR/env_block" \
        "$TMP_DIR/spawn" \
        "$TMP_DIR/keybinds" <<'PYEOF'
import sys

tmpl_path, out_path, kb_layout, kb_opt, mouse_sens, tp_sens, active_col, inactive_col, \
    output_f, env_f, spawn_f, binds_f = sys.argv[1:]

def read(f):
    try:
        with open(f) as fh:
            return fh.read()
    except Exception:
        return ''

with open(tmpl_path) as f:
    content = f.read()

content = content.replace('{{KB_LAYOUT}}',           kb_layout)
content = content.replace('{{KB_OPTIONS}}',          kb_opt)
content = content.replace('{{MOUSE_SENSITIVITY}}',   mouse_sens)
content = content.replace('{{TOUCHPAD_SENSITIVITY}}',tp_sens)
content = content.replace('{{ACTIVE_COLOR}}',        active_col)
content = content.replace('{{INACTIVE_COLOR}}',      inactive_col)
content = content.replace('{{OUTPUT_BLOCKS}}',       read(output_f))
content = content.replace('{{ENVIRONMENT_BLOCK}}',   read(env_f))
content = content.replace('{{SPAWN_AT_STARTUP}}',    read(spawn_f))
content = content.replace('{{DYNAMIC_KEYBINDS}}',    read(binds_f))

with open(out_path, 'w') as f:
    f.write(content)
PYEOF

    local py_exit=$?
    rm -rf "$TMP_DIR"

    if [ $py_exit -ne 0 ]; then
        echo "ERROR: Failed to generate niri config" >&2
        rm -f "$TMP_CONFIG"
        return 1
    fi

    # Diff-swap: only reload niri if something actually changed
    if diff -q "$NIRI_CONFIG" "$TMP_CONFIG" > /dev/null 2>&1; then
        rm -f "$TMP_CONFIG"
        echo "No niri config changes detected, skipping reload."
        return 0
    fi

    mv "$TMP_CONFIG" "$NIRI_CONFIG"
    echo "Niri config updated."

    if niri msg action load-config-file 2>/dev/null; then
        echo "Niri config reloaded."
    else
        echo "Niri not running — config will be picked up on next start."
    fi
}

# --compile: run once and exit (called by load_info.sh and matugen_reload.sh)
if [[ "$1" == "--compile" ]]; then
    compile_settings
    exit 0
fi

compile_settings

echo "Watching settings for changes..."

inotifywait -m -q -e close_write,moved_to --format '%w%f' \
    "$(dirname "$SETTINGS_FILE")" "$(dirname "$ENV_FILE")" | while read -r filepath; do

    if [[ "$filepath" == "$SETTINGS_FILE" ]]; then
        compile_settings
    fi

    if [[ "$filepath" == "$ENV_FILE" ]]; then
        echo ".env updated — forcing weather cache refresh..."
        if [ -x "$WEATHER_SCRIPT" ]; then
            "$WEATHER_SCRIPT" --getdata &
        else
            bash "$WEATHER_SCRIPT" --getdata &
        fi
    fi
done
